141	function captureInput(value: unknown): CapturedInput | undefined {
142		try {
143			if (!record(value) || Object.keys(value).sort().join(",") !== "catalog,handle") return undefined;
144			const catalog = Object.getOwnPropertyDescriptor(value, "catalog");
145			const handle = Object.getOwnPropertyDescriptor(value, "handle");
146			if (
147				catalog === undefined ||
148				!("value" in catalog) ||
149				!record(catalog.value) ||
150				handle === undefined ||
151				!("value" in handle) ||
152				!record(handle.value)
