162	function sameHead(left: PresentHead, right: PresentHead): boolean {
163		return (
164			left.closureDigest === right.closureDigest &&
165			left.generationId === right.generationId &&
166			left.objectId === right.objectId &&
167			left.revision === right.revision
168		);
