206	function validGenerationLineage(generations: readonly GenerationRecord[], facts: SealedAdoptionFacts): boolean {
207		const byId = new Map(generations.map((generation) => [generation.generationId, generation]));
208		if (byId.size !== generations.length) return false;
209		const current = byId.get(facts.currentHead.generationId);
210		const proposed = byId.get(facts.proposedHead.generationId);
211		if (
212			current === undefined ||
213			proposed === undefined ||
214			current.state !== "Superseded" ||
215			proposed.state !== "Adopted" ||
216			proposed.baseExpectedHead.kind !== "present" ||
217			!sameHead(proposed.baseExpectedHead, facts.currentHead) ||
218			!sameClosure(current.closure, facts.currentReferences) ||
219			!sameClosure(proposed.closure, facts.proposedReferences)
220		) {
221			return false;
222		}
223		for (const generation of generations) {
224			if (new Set(generation.closure.map(({ digest }) => digest)).size !== generation.closure.length) return false;
225			if (
226				generation.baseExpectedHead.kind === "present" &&
227				(generation.baseExpectedHead.generationId === generation.generationId ||
228					!byId.has(generation.baseExpectedHead.generationId))
229			) {
230				return false;
231			}
232		}
233		return facts.proposedHead.revision === facts.currentHead.revision + 1;
234	}
