436	async function verifySnapshot(
437		facts: Pick<SealedAdoptionFacts, "snapshotDeclaration" | "snapshotStore">,
438		chain: VerifiedChain
439	): Promise<VerifiedSnapshot | undefined> {
440		let scope: Awaited<ReturnType<SealedAdoptionFacts["snapshotStore"]["openScope"]>> | undefined;
441		let port: ReturnType<NonNullable<typeof scope>["verificationQuarantine"]["open"]> | undefined;
442		try {
443			const decoded = decodeSnapshotManifest({
444				exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
445				expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
446				profile: PROFILE,
447			});
448			scope = await facts.snapshotStore.openScope(facts.snapshotDeclaration);
449			port = scope.verificationQuarantine.open(new AbortController().signal);
450			const chunks: Uint8Array[] = [];
451			const readChunk = async (descriptor: Readonly<{ readonly index: number }>): Promise<Uint8Array | undefined> => {
452				const selected = decoded.chunks[descriptor.index];
453				if (selected === undefined) return undefined;
454				const bytes = await port?.read(selected);
455				if (
456					bytes === undefined ||
457					bytes.byteLength !== selected.byteLength ||
458					snapshotChunkDigest(selected.index, bytes) !== selected.digest
459				) {
460					return undefined;
461				}
462				chunks[selected.index] = Uint8Array.from(bytes);
463				return bytes;
464			};
465			const status = await scope.status();
466			if (status.kind === "verified") {
467				for (const descriptor of decoded.chunks) {
468					if ((await readChunk(descriptor)) === undefined) return undefined;
469				}
470			} else {
471				const verified = verifySnapshotStreamWithReceipt({
472					exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
473					expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
474					expectedScope: facts.snapshotDeclaration.scope,
475					profile: PROFILE,
476					quarantine: scope.verificationQuarantine,
477					source: Object.freeze({ read: readChunk }),
478				});
479				await verified.completion;
480				await scope.complete(await verified.receipt);
481			}
482			for (const descriptor of decoded.chunks) {
483				if (chunks[descriptor.index] === undefined && (await readChunk(descriptor)) === undefined) return undefined;
484			}
485			if (chunks.length !== decoded.chunks.length || chunks.some((chunk) => chunk === undefined)) return undefined;
486			const payloadBytes = new Uint8Array(chunks.reduce((total, chunk) => total + chunk.byteLength, 0));
487			let offset = 0;
488			for (const chunk of chunks) {
489				payloadBytes.set(chunk, offset);
490				offset += chunk.byteLength;
491			}
492			const payload = canonicalRecord(payloadBytes);
493			const manifest = canonicalRecord(facts.snapshotDeclaration.exactCanonicalManifestBytes);
494			if (
495				payload === undefined ||
496				manifest === undefined ||
497				facts.snapshotDeclaration.scope.manifestDigest !== chain.cut.snapshotManifestDigest ||
498				hex(hashDomain("ts-drp/snapshot-payload/v3", payloadBytes)) !== manifest.payloadDigest ||
499				payload.anchor !== manifest.anchor ||
500				payload.anchor !== chain.cut.previousAnchor ||
501				payload.objectId !== chain.cut.objectId ||
502				payload.epoch !== chain.cut.epoch ||
503				payload.archiveIndexRoot !== chain.cut.archiveIndexRoot ||
504				payload.blueprintDigest !== chain.cut.blueprintDigest ||
505				manifest.stateDigest !== chain.cut.stateDigest ||
506				manifest.aclDigest !== chain.cut.aclDigest ||
507				hex(hashDomain("ts-drp/state/v3", encodeCanonical(payload.application))) !== manifest.stateDigest ||
508				hex(hashDomain("ts-drp/latched-acl/v3", encodeCanonical(payload.acl))) !== manifest.aclDigest
509			) {
510				return undefined;
511			}
512			return Object.freeze({ exactCanonicalPayloadBytes: payloadBytes, manifest, payload });
513		} catch {
514			return undefined;
515		} finally {
516			try {
517				await port?.discard();
518			} finally {
519				await scope?.release();
520			}
521		}
522	}
