236	async function loadClosure(
237		store: AheDurableStore,
238		references: readonly GenerationRef[]
239	): Promise<readonly Readonly<{ readonly bytes: Uint8Array; readonly ref: GenerationRef }>[] | undefined> {
240		const candidates: Array<Readonly<{ readonly bytes: Uint8Array; readonly ref: GenerationRef }>> = [];
241		for (const ref of references) {
242			const loaded = await store.getBlob(ref.digest);
243			if (!loaded.ok || loaded.value === null) return undefined;
244			candidates.push(Object.freeze({ bytes: Uint8Array.from(loaded.value), ref: Object.freeze({ ...ref }) }));
245		}
246		return Object.freeze(candidates);
247	}
