249	async function readGenerationLineage(
250		store: AheDurableStore,
251		objectId: StorageObjectId
252	): Promise<readonly GenerationRecord[] | undefined> {
253		const generations: GenerationRecord[] = [];
254		const seenCursors = new Set<GenerationPageCursor>();
255		let cursor: GenerationPageCursor | undefined;
256		for (;;) {
257			const page = await store.readGenerationPage({
258				...(cursor === undefined ? {} : { cursor }),
259				limit: 128,
260				objectId,
261			});
262			if (!page.ok || (page.value.generations.length === 0 && page.value.nextCursor !== null)) return undefined;
263			generations.push(...page.value.generations);
264			if (page.value.nextCursor === null) return Object.freeze(generations);
265			if (seenCursors.has(page.value.nextCursor)) return undefined;
266			seenCursors.add(page.value.nextCursor);
267			cursor = page.value.nextCursor;
268		}
269	}
