271	async function recoverClosure(facts: SealedAdoptionFacts): Promise<RecoveredClosure | undefined> {
272		const recovered = await facts.store.recoverActiveGeneration(facts.objectId);
273		if (!recovered.ok || recovered.value.kind !== "active") return undefined;
274		const active = recovered.value;
275		const pending = sameHead(active.head, facts.proposedHead);
276		const adopted =
277			!pending &&
278			active.head.objectId === facts.proposedHead.objectId &&
279			active.head.revision === facts.proposedHead.revision + 1 &&
280			active.adoptedGeneration.baseExpectedHead.kind === "present" &&
281			sameHead(active.adoptedGeneration.baseExpectedHead, facts.proposedHead);
282		if (!pending && !adopted) return undefined;
283		if (
284			pending &&
285			(active.references.length !== facts.proposedReferences.length ||
286				active.adoptedGeneration.closure.length !== facts.proposedReferences.length ||
287				!facts.proposedReferences.every((ref, index) => sameRef(ref, active.references[index] as GenerationRef)) ||
288				!facts.proposedReferences.every((ref, index) =>
289					sameRef(ref, active.adoptedGeneration.closure[index] as GenerationRef)
290				))
291		) {
292			return undefined;
293		}
294		const closureDigest = digestClosure(active.references);
295		if (!closureDigest.ok || closureDigest.value !== active.head.closureDigest) return undefined;
296		const generations = await readGenerationLineage(facts.store, facts.objectId);
297		if (generations === undefined) return undefined;
298		if (pending && !validGenerationLineage(generations, facts)) return undefined;
299		if (adopted) {
300			const current = generations.find(({ generationId }) => generationId === facts.currentHead.generationId);
301			const proposed = generations.find(({ generationId }) => generationId === facts.proposedHead.generationId);
302			const successor = generations.find(({ generationId }) => generationId === active.head.generationId);
303			if (
304				current?.state !== "Superseded" ||
305				proposed?.state !== "Superseded" ||
306				successor?.state !== "Adopted" ||
307				proposed.baseExpectedHead.kind !== "present" ||
308				!sameHead(proposed.baseExpectedHead, facts.currentHead) ||
309				successor.baseExpectedHead.kind !== "present" ||
310				!sameHead(successor.baseExpectedHead, facts.proposedHead)
311			) {
312				return undefined;
313			}
314		}
315		const [currentCandidates, proposedCandidates] = await Promise.all([
316			loadClosure(facts.store, facts.currentReferences),
317			loadClosure(facts.store, facts.proposedReferences),
318		]);
319		return currentCandidates === undefined || proposedCandidates === undefined
320			? undefined
321			: Object.freeze({ currentCandidates, proposedCandidates });
322	}
