328	function verifyChain(facts: SealedAdoptionFacts, closure: RecoveredClosure): VerifiedChain | undefined {
329		const { closeResult } = facts;
330		const cutBytes = bytesForRef(closure.proposedCandidates, closeResult.cutValueRef);
331		const commitBytes = bytesForRef(closure.proposedCandidates, closeResult.commitQcRef);
332		const successorTrustBytes = bytesForRef(closure.proposedCandidates, closeResult.successorTrustRef);
333		const currentTrustBytes = closure.currentCandidates.find((candidate) =>
334			sameRef(candidate.ref, closeResult.currentTrustRef)
335		)?.bytes;
336		if (
337			cutBytes === undefined ||
338			commitBytes === undefined ||
339			successorTrustBytes === undefined ||
340			currentTrustBytes === undefined
