342			return undefined;
343		}
344		const opened = openCreatorSuccessorTrust({
345			currentTrust: facts.currentTrust,
346			exactCanonicalCommitQcBytes: commitBytes,
347			exactCanonicalCutValueBytes: cutBytes,
348			exactCanonicalTrustStateRecordBytes: successorTrustBytes,
349		});
350		if (
351			!opened.ok ||
352			opened.trust.currentAnchorDigest !== closeResult.successorAnchorDigest ||
353			opened.trust.currentEpoch !== closeResult.successorEpoch
354		) {
355			return undefined;
356		}
357		const advance = inspectCreatorTrustAdvance({
358			current: { candidates: closure.currentCandidates, closure: facts.currentReferences },
359			proofRefs: [closeResult.cutValueRef, closeResult.commitQcRef],
360			proposed: { candidates: closure.proposedCandidates, closure: facts.proposedReferences },
361		});
362		if (!advance.ok) return undefined;
363		const cut = canonicalRecord(cutBytes);
364		const currentTrustRecord = canonicalRecord(currentTrustBytes);
365		const successorTrustRecord = canonicalRecord(successorTrustBytes);
366		if (
367			cut === undefined ||
368			currentTrustRecord === undefined ||
369			successorTrustRecord === undefined ||
370			!(currentTrustRecord.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array) ||
371			!(successorTrustRecord.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array)
372		) {
373			return undefined;
374		}
375		const currentAnchor = canonicalRecord(currentTrustRecord.exactCanonicalCurrentAnchorPreimageBytes);
376		const successorAnchorBytes = Uint8Array.from(successorTrustRecord.exactCanonicalCurrentAnchorPreimageBytes);
377		const successorAnchor = canonicalRecord(successorAnchorBytes);
378		const currentEpoch = facts.currentTrust.currentEpoch;
379		const successorEpoch = opened.trust.currentEpoch;
380		if (
381			!Number.isSafeInteger(currentEpoch) ||
382			currentEpoch < 0 ||
383			!Number.isSafeInteger(successorEpoch) ||
384			successorEpoch !== currentEpoch + 1 ||
385			facts.closeResult.epoch !== currentEpoch ||
386			facts.closeResult.successorEpoch !== successorEpoch ||
387			currentTrustRecord.currentEpoch !== currentEpoch ||
388			successorTrustRecord.currentEpoch !== successorEpoch ||
389			currentAnchor?.epoch !== currentEpoch ||
390			successorAnchor?.epoch !== successorEpoch ||
391			successorAnchor?.previousAnchor !== facts.currentTrust.currentAnchorDigest
392		) {
393			return undefined;
394		}
395		const expectedCurrentProjectionKind = currentProjectionKind(currentEpoch);
396		const projections = closure.currentCandidates
397			.map(({ bytes }) => canonicalRecord(bytes))
398			.filter((candidate) => candidate?.kind === expectedCurrentProjectionKind);
399		const currentProjection = projections.length === 1 ? projections[0] : undefined;
400		if (
401			currentAnchor === undefined ||
402			successorAnchor === undefined ||
403			currentProjection === undefined ||
404			currentProjection.epoch !== currentEpoch ||
405			typeof currentProjection.artifactDigest !== "string" ||
406			typeof currentProjection.artifactId !== "string" ||
407			typeof currentProjection.blueprintDigest !== "string" ||
408			typeof currentProjection.catalogDigest !== "string" ||
409			typeof currentProjection.runtimeProfile !== "string" ||
410			currentProjection.blueprintDigest !== currentAnchor.blueprintDigest ||
411			currentProjection.blueprintDigest !== successorAnchor.blueprintDigest
412		) {
413			return undefined;
414		}
415		return Object.freeze({
416			currentAnchor,
417			currentEpoch,
418			currentProjectionKind: expectedCurrentProjectionKind,
419			currentTrustRecord,
420			currentCatalog: Object.freeze({
421				artifactDigest: currentProjection.artifactDigest,
422				artifactId: currentProjection.artifactId,
423				blueprintDigest: currentProjection.blueprintDigest,
424				catalogDigest: currentProjection.catalogDigest,
425				runtimeProfile: currentProjection.runtimeProfile,
426			}),
427			cut,
428			successorAnchor,
429			successorAnchorBytes,
430			successorEpoch,
431			successorTrust: opened.trust,
432			successorTrustRecord,
433		});
434	}
