475			}
476			const lineage = lineagePlan(generations, activeHead);
477			if (lineage.kind === "insufficient") return refused("D109A_ROLLBACK_INSUFFICIENT");
478			if (lineage.kind === "invalid") return refused("D109A_LINEAGE_INVALID");
479	
480			if (!validSnapshot(captured.snapshot)) return refused("D109A_SNAPSHOT_MISSING");
481			if (captured.availabilityPolicyDigest !== LOCAL_ONLY_POLICY_DIGEST) {
482				return refused("D109A_POLICY_UNSUPPORTED");
483			}
484			const issuance = copiedIssuance(captured.issuance, objectId, closedEpoch);
485			if (issuance === undefined) return refused("D109A_OUTBOX_INCOMPLETE");
486	
487			return Object.freeze({
488				ok: true as const,
489				plan: Object.freeze({
490					activeGenerationId: active.generationId,
491					availabilityPolicyDigest: LOCAL_ONLY_POLICY_DIGEST,
492					closedEpoch,
493					expectedHead: Object.freeze({ ...expectedHead }),
494					issuance,
495					lineageFloor: Object.freeze({
